$(function(){$("body").on("accountSelected","#customer_id",function(){getAttention($(this).attr("data-ac-id"))});var project_name_input=$("#project_name");var project_old_name=project_name_input.val();project_name_input.on("blur",function(){if($(this).val()!==project_old_name){$.getJSON("ajax_get_project_name.php",{project_name:$(this).val()},function(data){$("#name_err").html(data.is_duplicate==="Y"?"<b>Duplicate Project Name</b>":"");if(data.is_duplicate==="Y")$("#project_name").focus()})}})});function getAttention(account_id){$.get("../chart_of_account/ajax_get_attention.php",{account_id:account_id},function(data){$("#attention").val(data);console.log(data)})}